// FormChip — a single communication-form chip: a directional arrow glyph + label, with an optional
// dim note. Promoted from harvested into base-studio-code, refactored to use the real Row/Text/Chip
// primitives instead of local raw-div redeclarations.
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";

export interface CommunicationForm {
  id: string;
  label: string;
  color: string;
  arrow: string;
  blurb: string;
}

const DEMO_FORM: CommunicationForm = { id: "status", label: "status update", color: "var(--accent)", arrow: "→", blurb: "A brief on progress, blockers, and next steps; posted on a cadence." };

export function FormChip({ form = DEMO_FORM, note = false }: { form?: CommunicationForm; note?: boolean }) {
  return (
    <Row gap={7} align="center">
      <Chip color={form.color} style={{ fontWeight: 600, minWidth: 92 }}>
        {form.arrow} {form.label}
      </Chip>
      {note && <Text as="span" mono size={10} tone="dim">{form.blurb.split(";")[0]}</Text>}
    </Row>
  );
}
